	    public void EncodeBase64NVARCHARFields(APPaymentPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.PrintNotes)) //T4 find type == nText 
            {
                entityPM.PrintNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.PrintNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.InternalNotes)) //T4 find type == nText 
            {
                entityPM.InternalNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.InternalNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.TransferError)) //T4 find type == nText 
            {
                entityPM.TransferError = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.TransferError));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.BankAccountId)) //T4 find type == nText 
            {
                entityPM.BankAccountId = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.BankAccountId));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.VendorBankAddress)) //T4 find type == nText 
            {
                entityPM.VendorBankAddress = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.VendorBankAddress));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.VendorBankName)) //T4 find type == nText 
            {
                entityPM.VendorBankName = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.VendorBankName));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.VendorIBANNumber)) //T4 find type == nText 
            {
                entityPM.VendorIBANNumber = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.VendorIBANNumber));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.CancelationNotes)) //T4 find type == nText 
            {
                entityPM.CancelationNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.CancelationNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.ExternalPaymentNotes)) //T4 find type == nText 
            {
                entityPM.ExternalPaymentNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.ExternalPaymentNotes));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
